content.content:
  /api/v1/transformations/{transformationId}/form-records/{recordType}/{recordId}/custom-fields:
    parameters:
      - $ref: "#/components/parameters/TransformationId"
      - $ref: "#/components/parameters/FormRecordTypePath"
      - $ref: "#/components/parameters/FormRecordIdPath"
    get:
      tags: [forms]
      operationId: getFormRecordCustomFields
      summary: "The extension-field values of one record, with calculated fields evaluated (Not computable with the missing field named, never 0) and the version they were validated against; version 0 when none stored (transformation.read)."
      responses:
        "200":
          description: "OK."
          headers:
            ETag: { $ref: "#/components/headers/ETag" }
          content:
            application/json:
              schema: { $ref: "#/components/schemas/FormCustomValues" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "404": { $ref: "#/components/responses/NotFound" }
        "429": { $ref: "#/components/responses/RateLimited" }
    put:
      tags: [forms]
      operationId: putFormRecordCustomFields
      summary: "Replace the extension-field values of one record, validated before persistence against the pinned form_schema version: decimals as strings, percentages as fractions (12% -> 0.12), currency as amount + code, calculated fields refused. If-Match is the values' version, 0 to create (the record type's write permission). 400 validation.*; 409 form_record.conflict; 422 form_record.custom_field_unknown, custom_field_required, type_planned; form_schema.extensions_not_allowed."
      security:
        - sessionCookie: []
          csrfToken: []
      parameters:
        - $ref: "#/components/parameters/IfMatchOrZero"
      requestBody:
        required: true
        content:
          application/json:
            schema: { $ref: "#/components/schemas/FormCustomValuesPut" }
      responses:
        "200":
          description: "OK."
          headers:
            ETag: { $ref: "#/components/headers/ETag" }
          content:
            application/json:
              schema: { $ref: "#/components/schemas/FormCustomValues" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "404": { $ref: "#/components/responses/NotFound" }
        "409": { $ref: "#/components/responses/VersionConflict" }
        "422": { $ref: "#/components/responses/BusinessRule" }
        "428": { $ref: "#/components/responses/PreconditionRequired" }
        "429": { $ref: "#/components/responses/RateLimited" }
  /api/v1/transformations/{transformationId}/form-records/{recordType}/{recordId}/versions:
....
  /api/v1/transformations/{transformationId}/form-records/{recordType}/export:
    parameters:
      - $ref: "#/components/parameters/TransformationId"
      - $ref: "#/components/parameters/FormRecordTypePath"
    get:
      tags: [forms]
      operationId: exportFormRecords
      summary: "Export the records of one form in the transformation: source columns and the pinned version's extension fields, decimals as strings, Unknown and Not computable marked, never 0; at most 5000 rows (transformation.read). 422 form_export.too_large, form_record.type_planned."
      parameters:
        - $ref: "#/components/parameters/ExportFormatQuery"
        - $ref: "#/components/parameters/ExportLanguageQuery"
      responses:
        "200":
          description: "OK."
          content:
            text/csv:
              schema: { type: string, description: 'RFC 4180 UTF-8 with BOM; header labels in the requested language (ADR-0041 §5).' }
            application/json:
              schema: { $ref: "#/components/schemas/FormRecordExport" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "404": { $ref: "#/components/responses/NotFound" }
        "422": { $ref: "#/components/responses/BusinessRule" }
        "429": { $ref: "#/components/responses/RateLimited" }
  /api/v1/transformations/{transformationId}/form-records/{recordType}/bulk:
    parameters:
      - $ref: "#/components/parameters/TransformationId"
      - $ref: "#/components/parameters/FormRecordTypePath"
    post:
      tags: [forms]
      operationId: bulkUpdateFormRecords
      summary: "Bulk edit 1-100 records all-or-nothing: bulk-editable source columns through the register's own update, and extension-field values; every item carries its version (the record type's write permission). 409 form_record.bulk_conflict lists the stale items; 422 form_record.bulk_not_allowed, bulk_field_not_editable, bulk_too_many."
      security:
        - sessionCookie: []
          csrfToken: []
      requestBody:
        required: true
        content:
          application/json:
            schema: { $ref: "#/components/schemas/FormBulkUpdate" }
      responses:
        "200":
          description: "OK."
          content:
            application/json:
              schema: { $ref: "#/components/schemas/FormBulkUpdateResult" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "404": { $ref: "#/components/responses/NotFound" }
        "409": { $ref: "#/components/responses/VersionConflict" }
        "422": { $ref: "#/components/responses/BusinessRule" }
        "429": { $ref: "#/components/responses/RateLimited" }
  /api/v1/transformations/{transformationId}/form-drafts:
    parameters:
      - $ref: "#/components/parameters/TransformationId"
    get:
      tags: [forms]
      operationId: listFormDrafts
      summary: "The caller's own drafts in the transformation, newest first (transformation.read; own drafts only)."
      parameters:
        - $ref: "#/components/parameters/Cursor"
        - $ref: "#/components/parameters/Limit"
        - $ref: "#/components/parameters/FormRecordTypeQuery"
        - $ref: "#/components/parameters/FormDraftStatusQuery"
      responses:
        "200":
          description: "OK."
          content:
            application/json:
              schema: { $ref: "#/components/schemas/FormDraftPage" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "404": { $ref: "#/components/responses/NotFound" }
        "429": { $ref: "#/components/responses/RateLimited" }
    post:
      tags: [forms]
      operationId: createFormDraft
      summary: "Save a draft of a new record or of an existing record (with its current version) (the record type's write permission). 409 form_draft.open_exists; 422 form_record.type_planned."
      security:
        - sessionCookie: []
          csrfToken: []
      requestBody:
        required: true
        content:
          application/json:
            schema: { $ref: "#/components/schemas/FormDraftCreate" }
      responses:
        "201":
          description: "Created (open)."
          headers:
            Location: { $ref: "#/components/headers/Location" }
            ETag: { $ref: "#/components/headers/ETag" }
          content:
            application/json:
              schema: { $ref: "#/components/schemas/FormDraft" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "404": { $ref: "#/components/responses/NotFound" }
        "409": { $ref: "#/components/responses/Duplicate" }
        "422": { $ref: "#/components/responses/BusinessRule" }
        "429": { $ref: "#/components/responses/RateLimited" }
  /api/v1/transformations/{transformationId}/form-drafts/{draftId}:
    parameters:
      - $ref: "#/components/parameters/TransformationId"
      - $ref: "#/components/parameters/FormDraftId"
    get:
      tags: [forms]
      operationId: getFormDraft
      summary: "Reopen one of the caller's drafts; baseChanged tells whether the record moved past the draft's base version (owner only; others 404)."
      responses:
        "200":
          description: "OK."
          headers:
            ETag: { $ref: "#/components/headers/ETag" }
          content:
            application/json:
              schema: { $ref: "#/components/schemas/FormDraft" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "404": { $ref: "#/components/responses/NotFound" }
        "429": { $ref: "#/components/responses/RateLimited" }
    put:
      tags: [forms]
      operationId: updateFormDraft
      summary: "Replace the payload of an open draft (owner only). 422 form_draft.closed."
      security:
        - sessionCookie: []
          csrfToken: []
      parameters:
        - $ref: "#/components/parameters/IfMatch"
      requestBody:
        required: true
        content:
          application/json:
            schema: { $ref: "#/components/schemas/FormDraftUpdate" }
      responses:
        "200":
          description: "OK."
          headers:
            ETag: { $ref: "#/components/headers/ETag" }
          content:
            application/json:
              schema: { $ref: "#/components/schemas/FormDraft" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "404": { $ref: "#/components/responses/NotFound" }
        "409": { $ref: "#/components/responses/VersionConflict" }
        "422": { $ref: "#/components/responses/BusinessRule" }
        "428": { $ref: "#/components/responses/PreconditionRequired" }
        "429": { $ref: "#/components/responses/RateLimited" }
  /api/v1/transformations/{transformationId}/form-drafts/{draftId}/close:
    parameters:
      - $ref: "#/components/parameters/TransformationId"
      - $ref: "#/components/parameters/FormDraftId"
    post:
      tags: [forms]
      operationId: closeFormDraft
      summary: "Close an open draft as saved (after the record write succeeded) or discarded; a closed draft never changes (owner only). 422 form_draft.closed."
      security:
        - sessionCookie: []
          csrfToken: []
      parameters:
        - $ref: "#/components/parameters/IfMatch"
      requestBody:
        required: true
        content:
          application/json:
            schema: { $ref: "#/components/schemas/FormDraftClose" }
      responses:
        "200":
          description: "OK."
          headers:
            ETag: { $ref: "#/components/headers/ETag" }
          content:
            application/json:
              schema: { $ref: "#/components/schemas/FormDraft" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "404": { $ref: "#/components/responses/NotFound" }
        "409": { $ref: "#/components/responses/VersionConflict" }
        "422": { $ref: "#/components/responses/BusinessRule" }
        "428": { $ref: "#/components/responses/PreconditionRequired" }
        "429": { $ref: "#/components/responses/RateLimited" }
  /api/v1/procedure-definitions:
    get:
      tags: [procedures]
      operationId: listProcedureDefinitions
      summary: "Procedure definitions of a procedures version (default: the newest published), in order, with their M0152 parts and steps (procedure.read)."
      parameters:
        - $ref: "#/components/parameters/Cursor"
        - $ref: "#/components/parameters/Limit"
        - $ref: "#/components/parameters/ConfigVersionIdQuery"
        - $ref: "#/components/parameters/IncludeRemovedQuery"
      responses:

